'use strict';

var _objectSpread = require('@babel/runtime/helpers/objectSpread2');
var baseControllers = require('@toruslabs/base-controllers');
var auth = require('@web3auth/auth');
var PollingBlockTracker = require('../Block/PollingBlockTracker.js');
var transaction = require('../utils/transaction.js');
var cacheIdentifier = require('./cacheIdentifier.js');

function createChainIdMiddleware(getChainId) {
  return async ({
    request,
    next
  }) => {
    if (request.method !== "eth_chainId" && request.method !== "net_version") {
      return next();
    }
    const chainId = getChainId();
    if (chainId === "loading") {
      // if the current network state is not ready yet, make the actual request to the RPC provider
      return next();
    }
    // Otherwise, we will return the cached chainId from the network state
    if (request.method === "eth_chainId") {
      return chainId;
    }
    if (request.method === "net_version") {
      // convert to decimal
      return Number.parseInt(chainId, 16).toString(10);
    }
    return next();
  };
}
function createProviderConfigMiddleware(providerConfig) {
  return async ({
    request,
    next
  }) => {
    if (request.method === "eth_provider_config") {
      // can't do the direct cast because `interface ProviderConfig` doesn't satisfy the `Json` type
      return providerConfig;
    }
    return next();
  };
}
function createJsonRpcClient(providerConfig, networkConfig, getChainId, idleTimeTracker, analytics) {
  const {
    rpcTarget
  } = providerConfig;
  const fetchMiddleware = baseControllers.createFetchMiddleware({
    rpcTarget,
    providerConfig,
    analytics,
    transactionDecoder: transaction.transactionDecoder
  });
  const blockProvider = auth.providerFromMiddlewareV2(fetchMiddleware);
  const blockTracker = new PollingBlockTracker.PollingBlockTracker({
    config: _objectSpread(_objectSpread({}, networkConfig), {}, {
      provider: blockProvider
    }),
    state: {},
    idleTimeTracker
  });
  const jrpcEngineV2 = auth.JRPCEngineV2.create({
    middleware: [createChainIdMiddleware(getChainId), createProviderConfigMiddleware(providerConfig), baseControllers.createInflightCacheMiddleware({
      cacheIdentifierForRequest: cacheIdentifier.cacheIdentifierForRequest
    }), fetchMiddleware]
  });
  const networkMiddleware = jrpcEngineV2.asMiddleware();
  return {
    networkMiddleware,
    blockTracker
  };
}

exports.createChainIdMiddleware = createChainIdMiddleware;
exports.createJsonRpcClient = createJsonRpcClient;
exports.createProviderConfigMiddleware = createProviderConfigMiddleware;
